class CountIntervals { private val intervals=java.util.TreeMap<Int,Int>();private var covered=0L;fun add(leftValue:Int,rightValue:Int){var left=leftValue;var right=rightValue;var entry=intervals.floorEntry(left);if(entry==null||entry.value+1<left)entry=intervals.ceilingEntry(left);while(entry!=null&&entry.key<=right+1){left=minOf(left,entry.key);right=maxOf(right,entry.value);covered-=entry.value-entry.key+1L;intervals.remove(entry.key);entry=intervals.ceilingEntry(left)};intervals[left]=right;covered+=right-left+1L}fun count()=covered.toInt()}
